<script setup>
import { computed, onBeforeUnmount, ref, shallowRef, watch } from 'vue';
import ToolIntro from '../../components/ToolIntro.vue';
import { decodeJwt, jwtDates } from '../../utils/developerTools.js';
import { copyWithFeedback } from '../../utils/clipboard.js';
const token = ref(''), result = shallowRef(null), error = ref(''), now = ref(Date.now());
const dates = computed(() => result.value ? jwtDates(result.value.payload, now.value) : []);
const timer = setInterval(() => { now.value = Date.now(); },1000);
onBeforeUnmount(() => clearInterval(timer));
watch(token, () => { result.value = null; error.value = ''; });
function decode() { result.value = null; error.value = ''; try { result.value = decodeJwt(token.value); } catch (e) { error.value = e.message; } }
function sample() { const encode = value => btoa(JSON.stringify(value)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,''); const seconds = Math.floor(Date.now()/1000); token.value = `${encode({alg:'HS256',typ:'JWT'})}.${encode({sub:'demo-user',name:'Alex',iat:seconds,nbf:seconds,exp:seconds+3600})}.ZGVtby1zaWduYXR1cmU`; }
</script>
<template><section><ToolIntro title="JWT 解析" eyebrow="DEVELOPER / JWT" description="查看令牌中的声明与时间，快速理解 Header 和 Payload。" /><section class="panel utility-panel"><div class="panel-heading"><h2>JWT 内容</h2><a-button @click="sample">载入示例</a-button></div><label class="utility-field">Token（可带 Bearer 前缀）<a-textarea v-model:value="token" :rows="5" aria-label="JWT Token" placeholder="eyJhbGciOiJIUzI1NiJ9.…" spellcheck="false" class="utility-code" /></label><div class="utility-toolbar utility-gap"><a-button type="primary" @click="decode">解析 JWT</a-button><a-button @click="token = ''">清空</a-button><span class="utility-status">仅本地解析 · 未验证签名</span></div><p class="utility-note">时间状态仅依据声明和本机时钟计算。签名与令牌真实性需要由签发方验证。</p><a-alert v-if="error" class="utility-error" :message="error" type="error" role="alert" /></section><template v-if="result"><div class="utility-grid utility-gap"><section v-for="key in ['header','payload']" :key="key" class="panel utility-panel"><div class="panel-heading"><h2>{{ key === 'header' ? 'Header · 头部' : 'Payload · 载荷' }}</h2><a-button @click="copyWithFeedback(JSON.stringify(result[key],null,2), 'JSON 已复制。')">复制</a-button></div><pre class="utility-output utility-code">{{ JSON.stringify(result[key],null,2) }}</pre></section></div><section class="panel utility-panel utility-gap"><div class="panel-heading"><h2>时间声明</h2><span class="utility-status">UTC</span></div><div class="utility-table-wrap"><table class="utility-table"><thead><tr><th>声明</th><th>原值</th><th>UTC 时间</th><th>状态</th></tr></thead><tbody><tr v-for="date in dates" :key="date.key"><td>{{ date.key }}</td><td>{{ date.value }}</td><td>{{ date.date }}</td><td>{{ date.date === '无效 NumericDate' ? '无效值' : date.state }}</td></tr></tbody></table></div><p v-if="!dates.length" class="utility-note">该令牌未包含 iat、nbf 或 exp。</p><p class="utility-note">声明算法：{{ result.header.alg ?? '(未指定)' }} · 签名：{{ result.signature ? '存在，未验证' : '为空，未验证' }}</p></section></template></section></template>
